const step=(title,description,query)=>({title,description,query});
const walkthroughs={
0:[step('Start with a table','Every row is one customer. Read all columns first.','SELECT * FROM customers;'),step('Choose two columns','SELECT changes the visible columns, not the underlying rows.','SELECT name,city FROM customers;')],
3:[step('Start with customers','Chicago and Austin are values, not column names.','SELECT name,city FROM customers;'),step('Keep matching rows','WHERE keeps true comparisons. Missing city values do not match.','SELECT name,city FROM customers WHERE city=\'Chicago\';')],
10:[step('Read product rows','Two products belong to each category. The input grain is one product.','SELECT id,name,category FROM products;'),step('Count within groups','GROUP BY changes the grain to one category.','SELECT category,COUNT(*) AS product_count FROM products GROUP BY category;')],
15:[step('Identify the preserved side','Every customer must stay, even Hugo without an order.','SELECT * FROM customers;'),step('Inspect the joined rows','Customers repeat for each order. Hugo gets a NULL right-side id.','SELECT c.id,c.name,o.id AS order_id FROM customers c LEFT JOIN orders o ON o.customer_id=c.id;'),step('Count matching right-side ids','COUNT(o.id) ignores the unmatched NULL and gives Hugo zero.','SELECT c.name,COUNT(o.id) AS order_count FROM customers c LEFT JOIN orders o ON o.customer_id=c.id GROUP BY c.id,c.name;')],
31:[step('Inspect nullable relationships','NULL here means no referring viewer.','SELECT id,referred_by FROM viewers;'),step('See the NOT IN trap','A NULL in this subquery makes NOT IN unknown for nonmatches. Observe the empty result.','SELECT id FROM viewers WHERE id NOT IN(SELECT referred_by FROM viewers);'),step('Use an existence test','NOT EXISTS asks whether a matching referring relationship is absent.','SELECT v.id FROM viewers v WHERE NOT EXISTS(SELECT 1 FROM viewers r WHERE r.referred_by=v.id);')],
37:[step('The dangerous filter','Filtering success in WHERE loses the account without successful requests.','SELECT a.id,COUNT(r.id) AS successful_requests FROM ai_accounts a LEFT JOIN ai_requests r ON r.account_id=a.id WHERE r.status=\'success\' GROUP BY a.id;'),step('Filter matching rows in ON','All accounts stay; only successful requests can match.','SELECT a.id,COUNT(r.id) AS successful_requests FROM ai_accounts a LEFT JOIN ai_requests r ON r.account_id=a.id AND r.status=\'success\' GROUP BY a.id;')],
42:[step('Notice missing dates','Jan 3 and Jan 6 are absent. A row frame skips those dates.','SELECT * FROM daily_metrics ORDER BY day;'),step('Average observed rows','For Jan 4, the frame is Jan 1, Jan 2, Jan 4. That is three rows, not three calendar days.',lessons[42].tasks[0].answer),step('Build a complete calendar','Missing days become zero under the explicit business rule.','WITH RECURSIVE days(day) AS(SELECT \'2025-01-01\' UNION ALL SELECT date(day,\'+1 day\') FROM days WHERE day<\'2025-01-07\') SELECT d.day,COALESCE(m.watch_minutes,0) AS watch_minutes FROM days d LEFT JOIN daily_metrics m ON m.day=d.day ORDER BY d.day;'),step('Average calendar days','Now each row is one day. The frame’s three rows are also three days.',lessons[42].tasks[1].answer)],
44:[step('Find event retries','Logical event a has more than one physical row.','SELECT * FROM social_events WHERE event_key=\'a\' ORDER BY ingested_at,id;'),step('Number versions','The latest ingestion wins; id breaks timestamp ties.','SELECT id,event_key,ingested_at,ROW_NUMBER() OVER(PARTITION BY event_key ORDER BY ingested_at DESC,id DESC) AS rn FROM social_events ORDER BY event_key,rn;'),step('Keep one version',lessons[44].trap,lessons[44].tasks[0].answer)],
46:[step('Find first views','The denominator is members who entered the funnel.','SELECT member_id,MIN(event_at) AS viewed_at FROM social_events WHERE event_type=\'view\' GROUP BY member_id;'),step('Reconstruct valid stages','Observe member 3: the purchase before view is ignored, and a later valid purchase is kept.',funnelCTE+' SELECT * FROM funnel;'),step('Count people at each stage','LEFT JOIN leaves NULL at stages where a person drops off.',lessons[46].tasks[0].answer)],
47:[step('Define mature cohorts','Each row is one viewer in a cohort that can have a D7 observation.','SELECT id,signup_at,date(signup_at,\'+7 days\') AS return_day FROM viewers WHERE signup_at<=date(\'2025-01-15\',\'-7 days\');'),step('Mark exact-day returns','EXISTS counts each person at most once, even if several events occur on the return date.','SELECT v.id,v.signup_at,CASE WHEN EXISTS(SELECT 1 FROM watch_events w WHERE w.viewer_id=v.id AND date(w.watched_at)=date(v.signup_at,\'+7 days\')) THEN 1 ELSE 0 END AS retained FROM viewers v WHERE v.signup_at<=date(\'2025-01-15\',\'-7 days\');'),step('Report D7 retention','Retained people divided by all mature cohort members.',lessons[47].tasks[1].answer)],
48:[step('Find the previous timestamp','Order within member. Raw retries remain in this exercise.','SELECT id,member_id,event_at,LAG(event_at) OVER(PARTITION BY member_id ORDER BY event_at,id) AS previous_at FROM social_events ORDER BY member_id,event_at,id;'),step('Number the sessions','A new boundary occurs on the first event or a gap >=1800 seconds.',lessons[48].tasks[1].answer),step('Summarize sessions per member','The largest session number is the total number of sessions.',lessons[48].tasks[0].answer)],
49:[step('Observe join fan-out','Every request pairs with every invoice for the same account. Watch request 1 appear twice.','SELECT r.id AS request_id,i.id AS invoice_id,i.billed_amount FROM ai_requests r JOIN invoices i ON i.account_id=r.account_id WHERE r.account_id=1;'),step('Summarize requests first','One row per account is a safe grain for the final join.','SELECT account_id,COUNT(*) AS request_count FROM ai_requests GROUP BY account_id;'),step('Summarize invoices first','This is also one row per account.','SELECT account_id,SUM(billed_amount) AS billed_amount FROM invoices GROUP BY account_id;'),step('Join summaries','Neither side can multiply the other now.',lessons[49].tasks[0].answer)],
50:[step('Inspect split payments','Invoice 1 has two payments. Refunds also have multiple rows.','SELECT * FROM payments WHERE invoice_id=1;'),step('Aggregate payments','One summary row per invoice.','SELECT invoice_id,SUM(amount) AS paid_amount FROM payments GROUP BY invoice_id;'),step('Aggregate refunds','Join this summary, not individual refund rows.','SELECT invoice_id,SUM(amount) AS refund_amount FROM refunds GROUP BY invoice_id;'),step('Calculate the reconciliation gap',lessons[50].trap,lessons[50].tasks[0].answer)],
51:[step('Price a request','These teaching rates are fictional, in USD per million tokens.','SELECT r.id,r.model,(r.input_tokens*m.input_per_million+r.output_tokens*m.output_per_million)/1000000.0 AS usage_cost FROM ai_requests r JOIN model_rates m ON m.model=r.model WHERE r.status=\'success\';'),step('Compare aligned January totals','Billed revenue and usage costs share the same account and period grain.',lessons[51].tasks[1].answer)]
};
function stepsFor(id){return walkthroughs[id]||[step('Inspect the source',datasetCatalog[lessons[id].dataset].description,'SELECT * FROM '+datasetCatalog[lessons[id].dataset].tables[0]+' LIMIT 8;'),step('Run the reference',lessons[id].concept,lessons[id].example)];}
const moduleQuizzes=[
 {q:'SELECT name FROM customers returns what?',options:['Every customer row, with only the name column','Only customers with unique names','One aggregate row'],correct:0,why:'SELECT chooses columns. DISTINCT, WHERE, and aggregates change other aspects of the result.'},
 {q:'What happens when WHERE city = NULL is evaluated?',options:['It finds missing cities','The comparison is unknown; those rows are not kept','It finds the text NULL'],correct:1,why:'Use IS NULL for missing values. Ordinary comparisons with NULL evaluate to unknown.'},
 {q:'An account has no matching requests in a LEFT JOIN. Which count is zero?',options:['COUNT(*)','COUNT(account.id)','COUNT(request.id)'],correct:2,why:'The preserved account row still exists. COUNT(request.id) excludes the unmatched NULL.'},
 {q:'Two requests and three invoices belong to one account. How many rows can a raw join produce?',options:['Two','Three','Six'],correct:2,why:'Each request matches each invoice: 2 × 3. Aggregate both sides before joining if you need account totals.'},
 {q:'Which range includes every January timestamp and excludes February?',options:[">= '2025-01-01' AND < '2025-02-01'", "BETWEEN '2025-01-01' AND '2025-01-31'", "> '2025-01-01' AND <= '2025-02-01'"],correct:0,why:'A half-open interval handles the full last day and excludes the next boundary.'},
 {q:'Does ROWS BETWEEN 2 PRECEDING AND CURRENT ROW always represent three calendar days?',options:['Yes, whenever there is ORDER BY','Only when there is one complete row per calendar day','No, it always includes all preceding rows'],correct:1,why:'ROWS counts rows. Missing dates require a complete date spine for a calendar-day window.'},
 {q:'What belongs in a conversion-rate denominator for an assigned-user experiment?',options:['Only users who opened the app','All assigned users in the defined population','The number of purchase events'],correct:1,why:'Include assigned users who do nothing. Restricting the denominator to active users can bias the comparison.'}
];
const specificQuizzes={31:{q:'Why can NOT IN (SELECT nullable_key ...) unexpectedly return no rows?',options:['NULL can turn nonmatching comparisons into unknown','NOT IN removes all duplicates','The subquery is always empty'],correct:0,why:'Unknown does not pass WHERE. Filter NULLs from the list or use NOT EXISTS.'},41:{q:'Why does LAST_VALUE often return the current row?',options:['It always ignores ORDER BY','The default ordered frame may end at the current row','It only works with one row'],correct:1,why:'Extend the frame to UNBOUNDED FOLLOWING to include the final row in the partition.'},46:{q:'A person purchases before signing up, then never purchases again. Did they finish the ordered signup → purchase funnel?',options:['Yes, both event types exist','No, the purchase must occur on or after signup','Only if they viewed twice'],correct:1,why:'Sequence is part of the metric definition. Independent event counts cannot establish an ordered journey.'},47:{q:'Exact-day D7 retention means a user returns when?',options:['Any time during the first seven days','On signup date plus seven calendar days','At least seven times'],correct:1,why:'Exact-day, rolling-window, and unbounded retention use different definitions.'},48:{q:'With a gap rule of at least 30 minutes, does a 30-minute gap start a new session?',options:['No, only gaps over 30 minutes','Yes, use >=1800 seconds','Only for a new member'],correct:1,why:'The boundary is inclusive. Integer timestamp differences keep that definition precise.'},51:{q:'Is billed revenue minus model token cost the same as net profit?',options:['Yes','No; other costs and refunds may still be excluded','Only for free accounts'],correct:1,why:'This exercise defines a simplified contribution margin. It does not include all operating costs.'}};
function quizFor(id){return specificQuizzes[id]||moduleQuizzes[lessons[id].group];}
